#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum MergeBaseOutcome {
    MergeBaseReported {
        base_hex: String,
    },
    NoCommonAncestor,
    MergeBaseRefused {
        exit_code: i64,
        stderr: String,
    },
}

pub fn merge_base_exit_reported() -> i64 { 0 }

pub fn merge_base_exit_no_common_ancestor() -> i64 { 1 }

pub fn merge_base_outcome(exit_code: i64, stdout: String, stderr: String) -> Rc<MergeBaseOutcome> {
    if (exit_code.clone() == merge_base_exit_reported()) {
        Rc::new(MergeBaseOutcome::MergeBaseReported {
    base_hex: v1_rt::trim(stdout),
})
    } else {
        if (exit_code.clone() == merge_base_exit_no_common_ancestor()) {
            Rc::new(MergeBaseOutcome::NoCommonAncestor)
        } else {
            Rc::new(MergeBaseOutcome::MergeBaseRefused {
    exit_code: exit_code.clone(),
    stderr: stderr.clone(),
})
        }
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum MergeTreeOutcome {
    MergeTreeClean {
        tree_hex: String,
    },
    MergeTreeConflicted {
        tree_hex: String,
    },
    MergeTreeRefused {
        exit_code: i64,
        stderr: String,
    },
}

pub fn merge_tree_exit_clean() -> i64 { 0 }

pub fn merge_tree_exit_conflicted() -> i64 { 1 }

pub fn merge_tree_first_line(stdout: String) -> String {
    Rc::new(v1_rt::trim(stdout).split(&"\n".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).iter().cloned().fold("".to_string(), |acc: String, line: String| if (acc.clone() == "".to_string()) {
        v1_rt::trim(line.clone())
    } else {
        acc.clone()
    })
}

pub fn merge_tree_outcome(exit_code: i64, stdout: String, stderr: String) -> Rc<MergeTreeOutcome> {
    {
        let tree = merge_tree_first_line(stdout);
if (tree.clone() == "".to_string()) {
            Rc::new(MergeTreeOutcome::MergeTreeRefused {
    exit_code: exit_code.clone(),
    stderr: v1_rt::concat("git merge-tree produced no tree oid on stdout; stderr: ".to_string(), stderr.clone()),
})
        } else {
            if (exit_code.clone() == merge_tree_exit_clean()) {
                Rc::new(MergeTreeOutcome::MergeTreeClean {
    tree_hex: tree.clone(),
})
            } else {
                if (exit_code.clone() == merge_tree_exit_conflicted()) {
                    Rc::new(MergeTreeOutcome::MergeTreeConflicted {
    tree_hex: tree.clone(),
})
                } else {
                    Rc::new(MergeTreeOutcome::MergeTreeRefused {
    exit_code: exit_code.clone(),
    stderr: stderr.clone(),
})
                }
            }
        }
}
}

